// Storage. The playground starts every run with empty storage, so seed three
// saved expenses (on a real page they would be there from earlier visits).
const STORAGE_KEY = "pocket.expenses.v1";
if (localStorage.getItem(STORAGE_KEY) === null) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify([
    { id: "exp-1", label: "Coffee", amount: 450, category: "food" },
    { id: "exp-2", label: "Train", amount: 1220, category: "travel" },
    { id: "exp-3", label: "Lunch", amount: 1350, category: "food" },
  ]));
}

function loadExpenses() {
  try {
    const data = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "[]");
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}
function saveExpenses(expenses) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
}

// Pure helpers
const formatMoney = (cents) => `$${(cents / 100).toFixed(2)}`;
const totalCents = (expenses) => expenses.reduce((sum, e) => sum + e.amount, 0);
function validateExpense({ label, amount }) {
  const errors = {};
  if (label === "") errors.label = "Enter what you spent money on.";
  if (!Number.isFinite(amount) || amount <= 0) errors.amount = "Enter an amount greater than zero.";
  return errors;
}

// State
const state = { expenses: loadExpenses(), filter: "all" };
let idCounter = state.expenses.reduce((max, e) => Math.max(max, Number(e.id.split("-")[1])), 0);
const nextId = () => `exp-${++idCounter}`;

function update(changes) {
  Object.assign(state, changes);
  saveExpenses(state.expenses);
  render();
}

// Rendering
const form = document.querySelector("#expense-form");
const errorEl = document.querySelector("#form-error");
const list = document.querySelector("#expense-list");
const totalEl = document.querySelector("#total");
const filterSelect = document.querySelector("#filter");

// 1. Return the expenses that match state.filter ("all" shows everything)
function visibleExpenses() {
  return state.expenses;
}

function render() {
  const visible = visibleExpenses();
  list.replaceChildren();
  if (visible.length === 0) {
    const empty = document.createElement("li");
    empty.className = "empty";
    empty.textContent = "No expenses yet. Add your first one above.";
    list.append(empty);
  }
  for (const expense of visible) {
    const li = document.createElement("li");
    li.dataset.id = expense.id;
    const text = document.createElement("span");
    text.textContent = `${expense.label}: ${formatMoney(expense.amount)} (${expense.category})`;
    const button = document.createElement("button");
    button.type = "button";
    button.className = "delete";
    button.textContent = "Delete";
    button.setAttribute("aria-label", `Delete ${expense.label}`);
    li.append(text, button);
    list.append(li);
  }
  totalEl.textContent = `Total: ${formatMoney(totalCents(visible))}`;
}

// Events
form.addEventListener("submit", (event) => {
  event.preventDefault();
  const data = new FormData(form);
  const values = {
    label: data.get("label").trim(),
    amount: Math.round(Number(data.get("amount")) * 100),
    category: data.get("category"),
  };
  const errors = validateExpense(values);
  if (Object.keys(errors).length > 0) {
    errorEl.textContent = Object.values(errors).join(" ");
    return;
  }
  errorEl.textContent = "";
  update({ expenses: [...state.expenses, { id: nextId(), ...values }] });
  form.reset();
});

// 2. When #filter changes, update the filter
// 3. One delegated click listener on #expense-list that deletes an expense

render();

