    label: data.get("label").trim(),
    amount: Math.round(Number(data.get("amount")) * 100),
    category: data.get("category"),
  };
  const errors = validateExpense(values);
  if (Object.keys(errors).length > 0) {
    errorEl.textContent = Object.values(errors).join(" ");
    return;
  }
  errorEl.textContent = "";
  update({ expenses: [...state.expenses, { id: nextId(), ...values }] });
  form.reset();
});

filterSelect.addEventListener("change", () => {
  update({ filter: filterSelect.value });
});

list.addEventListener("click", (event) => {
  const button = event.target.closest(".delete");
  if (!button) return;
  const id = button.closest("li").dataset.id;
  update({ expenses: state.expenses.filter((e) => e.id !== id) });
});

render();

